scwin.btn1_onclick = function(e) {
    grd1.setFixedColumn(1);
};
scwin.btn2_onclick = function(e) {
    log = true;
    //alert("고정된 컬럼 index ==> " + grd1.getFixedColumnLastIndex());
};
scwin.btn3_onclick = function(e) {
    grd1.setFixedRow(2);
};
