    log1 = true;
    //alert("고정된 행 index ==> " + grd1.getFixedRow());
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 5. 브라우저에서 컬럼 고정 버튼을 클릭한다.
    //5. In the browser, click the Lock column button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 5. 1번에서 설정한대로 name1 컬럼이 고정된다.
    //5. The name1 column is fixed as set in # 1.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd1').getFixedColumnLastIndex() == 1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 6. getFixedColumnLastIndex() 버튼을 클릭한다.
    //6. Click the getFixedColumnLastIndex () button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 6. 고정된 컬럼의 index 팝업이 생성된다. (1)
    //6. The index popup of the fixed column is created. (One)
    WebSquare.wUnit.addCommand("assert", "log", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 7. 행 고정 버튼을 클릭한다.
    //7. Click the Row Lock button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 7. 3번에서 설정한대로 2 행이 고정된다.
    //7. Two lines are fixed as set in step 3.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd1').getFixedRow() == 2", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 8. getFixedRow() 버튼을 클릭한다.
    //8. Click the getFixedRow () button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn4').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 8. 고정된 행의 index 팝업이 생성된다. (2)
    //8. An index pop-up of fixed rows is created. (2)
    WebSquare.wUnit.addCommand("assert", "log1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = false;
    window.log1 = false;
    scwin.init();
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 21-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
